using UnityEngine;using UnityEditor;using Unity.Profiling;using System.IO;using System.Linq;
public static class PerformanceSample{static ProfilerRecorder cpu,gc;static double until;static int frame,n;static double ms,bytes;public static string Run(){cpu=ProfilerRecorder.StartNew(ProfilerCategory.Internal,"Main Thread",1);gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame",1);until=EditorApplication.timeSinceStartup+8;frame=Time.frameCount;n=0;ms=bytes=0;EditorApplication.update+=Tick;return "Sampling 8 seconds";}static void Tick(){if(Time.frameCount!=frame){frame=Time.frameCount;n++;ms+=Time.unscaledDeltaTime*1000;bytes+=gc.LastValue;}if(EditorApplication.timeSinceStartup<until)return;EditorApplication.update-=Tick;var lights=Object.FindObjectsByType<Light>(FindObjectsSortMode.None);File.WriteAllText("Library/PerformanceSample.txt",$"frames={n}; ms={ms/System.Math.Max(1,n):F2}; fps={1000/(ms/System.Math.Max(1,n)):F1}; gcBytes={bytes/System.Math.Max(1,n):F0}; mainNs={cpu.LastValue}; lights={lights.Length}; shadowLights={lights.Count(l=>l.enabled&&l.shadows!=LightShadows.None)}; renderers={Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).Length}");cpu.Dispose();gc.Dispose();}}
